var SIGMA = 5.670374419e-8; // Stefan-Boltzmann constant, W·m⁻²·K⁻⁴
function radiance(T){ if(!(T>=0)) return NaN; return SIGMA*Math.pow(T,4); } // emitted power per unit area, W/m²
function power(T, A){ if(!(T>=0)||!(A>0)) return NaN; return SIGMA*A*Math.pow(T,4); } // total radiated power, W
var EXPORTS = { radiance:radiance, power:power, SIGMA:SIGMA };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StefanForgePure = EXPORTS; }
